(function(root){'use strict';
const modules=['grammar','reading','vocabulary','listening'];
const labels={grammar:'语法',reading:'阅读',vocabulary:'词汇',listening:'听力'};
const tags={target_relation:'に対して / にとって',habit_intention:'ことにしている · 习惯决定',habit_accidental:'こともある · 偶发',negation_scope:'わけではない · 否定范围',causative_obligation:'使役 ＋ わけにはいかない',alternative_preference:'ぐらいなら · 条件关系',conjecture:'のではないか · 推测',inference:'わけだ · 原因解释',definition:'というのは · 定义',insufficient_condition:'だけでは · 不充分条件',minimal_extent:'くらい · 最低限度',scope_overgeneralization:'阅读 · 限定范围',potential_form:'可能形',aspect_nominalizer:'ところ · 名词化',desire_form:'たい形 · 愿望',concession:'让步关系',particle:'助词与主语关系',causal_connection:'ので / から · 因果连接',negative_stem:'ない形 · 词干',aspect:'动作完成与体貌',obligation_connection:'なければならない · 接续',suru_conjugation:'する · 动词变化',disregard_vs_time:'もかまわず · 不顾',implicit_object:'省略对象',overinference:'过度推断',deadline_precision:'时间范围精度',set_aside_vs_addition:'はともかく · 暂且不论',duration:'期间数量表达',potential_vs_simple_negative:'可能否定 / 普通否定',simple_negative_vs_obligation:'普通否定 / 义务',kana_reading:'词汇读音',kanji_selection:'汉字选择'};
function validate(data){if(!data||data.schema_version!=='1.0'||!Array.isArray(data.attempts))throw Error('需要 schema_version="1.0" 与 attempts 数组');const ids=new Set();for(const a of data.attempts){if(!a||typeof a.id!=='string'||!a.id.trim()||ids.has(a.id))throw Error('记录 ID 缺失或重复');ids.add(a.id);if(!modules.includes(a.module)||!['correct','incorrect','partial'].includes(a.result)||!['independent','hinted','immediate','unknown_external'].includes(a.support)||!['first','first_recorded_external','retest'].includes(a.attempt_kind)||typeof a.accuracy_eligible!=='boolean')throw Error('记录 '+a.id+' 的模块、结果或作答条件无效');if(!/^\d{4}-\d{2}-\d{2}$/.test(a.date)||isNaN(Date.parse(a.date))||new Date(a.date).toISOString().slice(0,10)!==a.date)throw Error('记录日期无效');for(const key of ['canonical_key','prompt'])if(typeof a[key]!=='string'||!a[key].trim())throw Error('记录缺少 '+key);if(!Array.isArray(a.error_tags)||a.error_tags.some(x=>typeof x!=='string')||!Array.isArray(a.source_ids)||!a.source_ids.length||a.source_ids.some(x=>typeof x!=='string'))throw Error('错误标签或来源格式无效');}return data;}
function stable(x){if(Array.isArray(x))return '['+x.map(stable).join(',')+']';if(x&&typeof x==='object')return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+stable(x[k])).join(',')+'}';return JSON.stringify(x)}
function merge(base,incoming){validate(base);validate(incoming);const map=new Map(base.attempts.map(a=>[a.id,a]));let added=0;for(const a of incoming.attempts){if(map.has(a.id)){if(stable(map.get(a.id))!==stable(a))throw Error('ID 冲突：'+a.id+'；未导入任何记录，请先核对来源。')}else{map.set(a.id,a);added++}}return {data:{...base,attempts:[...map.values()]},added};}
function inMode(a,mode){if(mode==='baseline')return a.accuracy_eligible&&['first','first_recorded_external'].includes(a.attempt_kind)&&['independent','unknown_external'].includes(a.support);if(mode==='independent')return a.accuracy_eligible&&a.support==='independent'&&a.attempt_kind==='first';if(mode==='assisted')return a.attempt_kind==='retest'||a.support==='hinted'||a.support==='immediate';return true}
function filter(data,f){return data.attempts.filter(a=>inMode(a,f.mode)&&(!f.from||a.date>=f.from)&&(!f.to||a.date<=f.to)&&(f.module==='all'||a.module===f.module))}
function stats(rows){const total=rows.length,correct=rows.filter(a=>a.result==='correct').length;return {total,correct,rate:total?correct/total:null};}
function keys(a){return a.module==='vocabulary'?[a.canonical_key]:a.error_tags.length?[...new Set(a.error_tags)].map(t=>a.module+':tag:'+t):[a.canonical_key]}
function keyLabel(key){const tag=key.split(':tag:')[1];return tag?(tags[tag]||tag):key.replace(/^[^:]+:/,'')}
function rank(rows){const map=new Map();for(const a of rows.filter(a=>a.result!=='correct'))for(const key of keys(a)){if(!map.has(key))map.set(key,{key,label:keyLabel(key),count:0,ids:[],independent:0,external:0,assisted:0,module:a.module});const g=map.get(key);g.count++;g.ids.push(a.id);if(a.support==='independent'&&a.attempt_kind==='first')g.independent++;else if(a.support==='unknown_external')g.external++;else g.assisted++}return [...map.values()].sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label,'zh'));}
const api={modules,labels,tags,validate,merge,filter,stats,rank,keys,keyLabel,inMode};root.N2Model=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
